message.content:
{
  "full_script": "Flegillo, Bob, Pixie. No te cortes el pelo hasta ver esto. HairApp me dio muchísimas opciones para encontrar el peinado que mejor me queda. Y sí, de verdad encontré el ideal. En serio, estuve a punto de arruinarme el corte. Créeme, pruébalo antes de tocarte el pelo.",
  "lines": [
    {
      "start": 0.0,
      "end": 2.1,
      "speaker": "Speaker 1",
      "text": "Flegillo, Bob, Pixie."
    },
    {
      "start": 2.1,
      "end": 4.2,
      "speaker": "Speaker 1",
      "text": "No te cortes el pelo hasta ver esto."
    },
    {
      "start": 4.2,
      "end": 8.5,
      "speaker": "Speaker 1",
      "text": "HairApp me dio muchísimas opciones para encontrar el peinado que mejor me queda."
    },
    {
      "start": 8.5,
      "end": 11.0,
      "speaker": "Speaker 1",
      "text": "Y sí, de verdad encontré el ideal."
    },
    {
      "start": 11.0,
      "end": 13.8,
      "speaker": "Speaker 1",
      "text": "En serio, estuve a punto de arruinarme el corte."
    },
    {
      "start": 13.8,
      "end": 16.5,
      "speaker": "Speaker 1",
      "text": "Créeme, pruébalo antes de tocarte el pelo."
    }
  ]
}

